  (* [comment removed for export] *)
  Lemma w4_inner : forall (r : nat) mm ws (b0 b1 b2 b3 : word) IP0 IP1 IP2 IP3 B0 B1 B2 B3 DL OL
                          (x1 x5 x7 x8 x9 x10 x11 x12 x13 x15 x16 x17 x19 x20 x25 x30 : word),
    W4M mm (Z_to_bv 64 OL) (Z_to_bv 64 B3) (Z_to_bv 64 0xff34) (Z_to_bv 64 B2) (Z_to_bv 64 B1) (Z_to_bv 64 B0)
           (Z_to_bv 64 0x20dc4) (Z_to_bv 64 DL) ws ->
    (1 <= r)%nat -> OL = B3 + DL + 5 * Z.of_nat r -> OL <= DST + dcap ->
    B0 <= B3 -> B1 <= B3 -> B2 <= B3 -> 0 <= DL -> DST <= B0 -> DST <= B1 -> DST <= B2 -> DST <= B3 ->
    SS + 7 * Z.of_nat r <= IP0 -> IP0 + 8 <= SS + n -> SS + 7 * Z.of_nat r <= IP1 -> IP1 + 8 <= SS + n ->
    SS + 7 * Z.of_nat r <= IP2 -> IP2 + 8 <= SS + n -> SS + 7 * Z.of_nat r <= IP3 -> IP3 + 8 <= SS + n ->
    (forall mm' (b0' b1' b2' b3' : word) IP0' IP1' IP2' IP3' (x1' x5' x7' x8' x9' x11' x12' x13' x15' x16' x17' x19' x20' x25' x30' : word),
       W4M mm' (Z_to_bv 64 OL) (Z_to_bv 64 B3) (Z_to_bv 64 0xff34) (Z_to_bv 64 B2) (Z_to_bv 64 B1) (Z_to_bv 64 B0)
           (Z_to_bv 64 0x20dc4) (Z_to_bv 64 (DL + 5 * Z.of_nat r)) ws ->
       SS <= IP0' -> IP0' + 8 <= SS + n -> SS <= IP1' -> IP1' + 8 <= SS + n ->
       SS <= IP2' -> IP2' + 8 <= SS + n -> SS <= IP3' -> IP3' + 8 <= SS + n ->
       evtF asegs RNG POST (W4H 0x8eecc mm' b0' b1' b2' b3' IP0' IP1' IP2' IP3' B3 x1' x5' x7' x8' x9'
                                (Z_to_bv 64 OL) x11' x12' x13' x15' x16' x17' x19' x20' x25' (Z_to_bv 64 0x20dc4) x30')) ->
    evtF asegs RNG POST (W4H 0x8ef70 mm b0 b1 b2 b3 IP0 IP1 IP2 IP3 B3 x1 x5 x7 x8 x9 x10 x11 x12 x13 x15 x16 x17
